// The town on the ground (docs/town.md): the layout contract with the Blender build, the catalog entries of its
// pieces, the URL rule that decides whether a session starts in the town, and where town models are fetched from.
// Pure and deterministic; the numbers come from scenes/town-data.js (regenerated by art/town/build_town.py).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { TOWN_DATA } from '../../src/scenes/town-data.js';
import { TOWN_ORIGIN, TOWN_SPAWN, TOWN_ALTAR, TOWN_ALTAR_SPAWN, TOWN_ROUTE, TOWN_ROUTE_LENGTH, TOWN_KILL_Y, TOWN_FOG_BASE_Y, TOWN_MIST_LEVEL, TOWN_ATMOSPHERE, TOWN_CAMERA, TOWN_SKY, yawToward, TOWN_KINDS, TOWN_PIECES, TOWN_TERRAIN, TOWN_ALTAR_ASSET,
  townToWorld, townToLocal, routeLength, altarDistance, inAltarRange, altarWake, townFlatGround, headingToward, SPAWN_ADVANCE } from '../../src/scenes/town-layout.js';
import { SPAWN, KILL_Y } from '../../src/scenes/layout.js';
import { ASSETS, TOWN_ASSETS, ALL_ASSETS, LOAD_DISTANCE, TRIANGLE_BUDGET, assetByName, isValidModelName, isValidModelDir, modelUrl, versionedModelUrl } from '../../src/render/asset-catalog.js';
import { townPlan } from '../../src/ui/loading.js';
import { OUTSIDE_KILL_Y } from '../../src/scenes/town-outside.js';
import { scanModels, modelListSource, MODEL_SUBDIRS } from '../../build/model-list.js';
import { chunkFor } from '../../build/chunks.js';

const SHELL_ORIGIN = [0, 300, 0]; // scenes/shell.js (not imported: that module needs three.js and the Vite model list)
const CAMERA_FAR = 500;

test('town data: the shape the client reads', () => {
  for (const k of ['spawn', 'altar', 'route', 'pieces', 'killY', 'size']) assert.ok(k in TOWN_DATA, k);
  const v3 = (p, what) => { assert.ok(Array.isArray(p) && p.length === 3 && p.every(Number.isFinite), what + ' is a point'); };
  v3(TOWN_DATA.spawn.position, 'spawn'); assert.ok(Number.isFinite(TOWN_DATA.spawn.heading));
  for (const k of ['position', 'stand', 'focus']) v3(TOWN_DATA.altar[k], 'altar.' + k);
  assert.ok(TOWN_DATA.altar.radius > 1 && TOWN_DATA.altar.radius < 12);
  assert.ok(TOWN_DATA.route.length >= 2);
  for (const p of TOWN_DATA.route) v3(p, 'route point');
  for (const p of TOWN_DATA.pieces) { v3(p.position, p.name); v3(p.center, p.name + ' center'); assert.ok(p.radius > 0, p.name + ' radius'); }
});

test('town layout: far from the archipelago and the Shell interior, beyond the camera far plane', () => {
  const [w, d] = TOWN_DATA.size;
  const reach = Math.hypot(w, d) / 2 + 300; // the playable area plus the sky impostor's distance
  assert.ok(Math.hypot(...TOWN_ORIGIN) > 700);
  assert.ok(Math.hypot(...TOWN_ORIGIN) - reach - 80 > CAMERA_FAR, 'the island never enters a town frame');
  assert.ok(Math.hypot(TOWN_ORIGIN[0] - SHELL_ORIGIN[0], TOWN_ORIGIN[1] - SHELL_ORIGIN[1], TOWN_ORIGIN[2] - SHELL_ORIGIN[2]) > 700);
  assert.deepEqual(townToLocal(townToWorld([1, 2, 3])), [1, 2, 3]);
  // Iris starts SPAWN_ADVANCE metres up the street from the plan's gate point (the gate arch squeezed the camera there).
  const local = townToLocal(TOWN_SPAWN.position), plan = TOWN_DATA.spawn.position;
  assert.ok(Math.abs(Math.hypot(local[0] - plan[0], local[2] - plan[2]) - SPAWN_ADVANCE) < 1e-6 && local[1] === plan[1]);
  assert.ok(local[2] < plan[2], 'toward the altar');
});

test('town layout: pieces have valid unique names and kinds the catalog knows', () => {
  const names = TOWN_DATA.pieces.map((p) => p.name);
  assert.equal(new Set(names).size, names.length, 'unique names');
  for (const p of TOWN_DATA.pieces) {
    assert.ok(isValidModelName(p.name), p.name);
    assert.match(p.name, /^town_/, 'town pieces carry the town_ prefix');
    assert.ok(!/_m$|_inspect$/.test(p.name), p.name + ' must not look like a variant file');
    assert.ok(TOWN_KINDS.includes(p.kind), p.name + ' kind ' + p.kind);
    assert.ok(LOAD_DISTANCE[p.kind] > 0, 'load distance for ' + p.kind);
    assert.ok(TRIANGLE_BUDGET[p.kind].runtime > 0, 'triangle budget for ' + p.kind);
    assert.ok(!ASSETS.some((a) => a.name === p.name), p.name + ' repeats an archipelago asset');
  }
  assert.ok(names.includes(TOWN_TERRAIN), 'the terrain piece carries the ground');
  assert.ok(names.includes(TOWN_ALTAR_ASSET), 'the altar is its own piece');
  assert.equal(TOWN_PIECES.length, TOWN_DATA.pieces.length);
  assert.deepEqual(TOWN_PIECES.filter((p) => p.visualOnly).map((p) => p.kind), TOWN_DATA.pieces.filter((p) => p.kind === 'town_sky').map((p) => p.kind));
  assert.deepEqual(TRIANGLE_BUDGET.town_hero, { runtime: 16000, inspect: 60000 });
  assert.equal(TRIANGLE_BUDGET.town_terrain.runtime, 120000);
  assert.equal(TRIANGLE_BUDGET.town_block.runtime, 120000);
  assert.equal(TRIANGLE_BUDGET.town_sky.runtime, 20000);
});

test('town catalog: one entry per piece, bounds from the data, no greybox', () => {
  assert.equal(TOWN_ASSETS.length, TOWN_DATA.pieces.length + (TOWN_DATA.interiors || []).length, 'the pieces and the shop interiors');
  for (const it of TOWN_DATA.interiors || []) assert.ok(assetByName(it.name).noGreybox, it.name);
  assert.equal(ALL_ASSETS.length, ASSETS.length + TOWN_ASSETS.length);
  for (const p of TOWN_DATA.pieces) {
    const a = assetByName(p.name);
    assert.ok(a && a.town && a.noGreybox, p.name);
    assert.equal(a.kind, p.kind);
    assert.equal(a.radius, p.radius);
    assert.deepEqual(a.centerOffset.map((v, i) => v + p.position[i]), p.center);
    assert.ok(a.height >= 1 && a.label.length > 3);
  }
  assert.equal(assetByName('town_altar').label, 'Tournament altar');
  assert.equal(assetByName('anchor').noGreybox, undefined, 'archipelago assets keep their greybox');
});

test('town layout: the jury walk is 30 to 50 m, starts at the spawn, ends at the altar stand inside the prompt radius', () => {
  assert.ok(TOWN_ROUTE_LENGTH >= 30 && TOWN_ROUTE_LENGTH <= 50, 'route length ' + TOWN_ROUTE_LENGTH.toFixed(1));
  assert.equal(routeLength(TOWN_ROUTE).toFixed(6), TOWN_ROUTE_LENGTH.toFixed(6), 'the origin shift keeps lengths');
  const first = TOWN_DATA.route[0], last = TOWN_DATA.route[TOWN_DATA.route.length - 1];
  assert.ok(Math.hypot(first[0] - TOWN_DATA.spawn.position[0], first[2] - TOWN_DATA.spawn.position[2]) < 1.5, 'the route starts at the spawn');
  assert.ok(Math.hypot(last[0] - TOWN_DATA.altar.stand[0], last[2] - TOWN_DATA.altar.stand[2]) < 1.5, 'the route ends at the altar stand');
  const stand = Math.hypot(TOWN_DATA.altar.stand[0] - TOWN_DATA.altar.position[0], TOWN_DATA.altar.stand[2] - TOWN_DATA.altar.position[2]);
  assert.ok(stand < TOWN_DATA.altar.radius, 'the stand is inside the prompt radius');
  assert.ok(stand > 0.8, 'the stand is not inside the altar stone');
  assert.ok(inAltarRange(TOWN_ALTAR.stand) && !inAltarRange(TOWN_SPAWN.position));
  assert.ok(altarDistance(TOWN_SPAWN.position) > TOWN_ALTAR.radius * 2.5, 'the altar sleeps while Iris is at the gate');
  const [w, d] = TOWN_DATA.size;
  for (const p of TOWN_DATA.route) assert.ok(Math.abs(p[0]) <= w / 2 && Math.abs(p[2]) <= d / 2, 'the route stays inside the playable area');
  for (const p of TOWN_DATA.route) assert.ok(p[1] > TOWN_DATA.killY + 3, 'the route stays above the kill height');
});

test('town layout: kill height, fog and mist sit below the town; the altar spawn faces the altar', () => {
  assert.equal(TOWN_KILL_Y, TOWN_ORIGIN[1] + Math.min(TOWN_DATA.killY, OUTSIDE_KILL_Y)); // the hillside beyond the gate runs lower than the streets
  assert.ok(TOWN_KILL_Y > KILL_Y + 500, 'an island kill height would never catch a fall in the town');
  const low = Math.min(...TOWN_DATA.route.map((p) => p[1]));
  assert.ok(TOWN_FOG_BASE_Y < TOWN_ORIGIN[1] + low && TOWN_MIST_LEVEL < TOWN_FOG_BASE_Y);
  if (TOWN_SKY) {
    const d = Math.hypot(TOWN_SKY.center[0] - TOWN_ALTAR.stand[0], TOWN_SKY.center[1] - TOWN_ALTAR.stand[1], TOWN_SKY.center[2] - TOWN_ALTAR.stand[2]);
    assert.ok(d < TOWN_CAMERA.far && TOWN_CAMERA.far >= 700, 'the islands in the sky are inside the town camera far plane, centre at ' + d.toFixed(0) + ' m');
    assert.ok(Math.hypot(...TOWN_ORIGIN) - TOWN_CAMERA.far > 200, 'the real archipelago stays out of the town camera');
  }
  assert.equal(yawToward([0, 0, 5], [0, 0, 0]), 0, 'yaw 0 looks toward -Z');
  assert.equal(TOWN_ATMOSPHERE.fogBaseY, TOWN_FOG_BASE_Y);
  assert.ok(TOWN_CAMERA.dist >= 6 && TOWN_CAMERA.dist <= 7 && TOWN_CAMERA.minPitch < 0, 'a close street camera that can look up at the sky islands');
  assert.deepEqual(TOWN_ALTAR_SPAWN.position, TOWN_ALTAR.stand);
  const h = TOWN_ALTAR_SPAWN.heading, s = TOWN_ALTAR.stand, a = TOWN_ALTAR.position;
  const dot = Math.sin(h) * (a[0] - s[0]) + Math.cos(h) * (a[2] - s[2]);
  assert.ok(dot > 0.99 * Math.hypot(a[0] - s[0], a[2] - s[2]), 'heading 0 faces +Z; the altar spawn looks at the altar');
  assert.equal(headingToward([0, 0, 0], [0, 0, 5]), 0);
  const g = townFlatGround();
  assert.equal(g.top, TOWN_SPAWN.position[1]);
  assert.ok(g.min[0] < TOWN_ALTAR.stand[0] && g.max[0] > TOWN_ALTAR.stand[0] && g.min[2] < TOWN_ALTAR.stand[2] && g.max[2] > TOWN_SPAWN.position[2]);
  assert.ok(Math.hypot(SPAWN[0] - TOWN_SPAWN.position[0], SPAWN[1] - TOWN_SPAWN.position[1], SPAWN[2] - TOWN_SPAWN.position[2]) > 700);
});

test('altar core: asleep far away, awake at the prompt radius, monotone between', () => {
  const r = TOWN_ALTAR.radius;
  assert.equal(altarWake(r * 4, r), 0);
  assert.equal(altarWake(r * 2.5, r), 0);
  assert.equal(altarWake(r, r), 1);
  assert.equal(altarWake(0, r), 1);
  let prev = 0;
  for (let d = r * 2.5; d >= r; d -= r * 0.1) { const w = altarWake(d, r); assert.ok(w >= prev - 1e-9 && w >= 0 && w <= 1); prev = w; }
});

test('town plan: the town is the default; deep links skip it unless ?town= asks; ?skip=town always skips', () => {
  const on = { town: true, spawn: 'gate', flat: false }, off = { town: false, spawn: 'gate', flat: false };
  const plan = (q) => { const p = new URLSearchParams(q); return townPlan({ skip: p.get('skip'), town: p.get('town'), play: p.get('play'), cinematic: p.get('cinematic'), view: p.get('view'), film: p.get('film') }); };
  assert.deepEqual(townPlan(), on);
  assert.deepEqual(plan(''), on, 'the lobby path');
  assert.deepEqual(plan('demo=judge'), on, 'the jury link goes through the lobby into the town');
  assert.deepEqual(plan('lang=ru&tier=low&motion=reduce'), on);
  assert.deepEqual(plan('skip=town'), off);
  assert.deepEqual(plan('demo=judge&skip=town'), off);
  assert.deepEqual(plan('play=direct'), off, 'the QA link keeps its meaning');
  assert.deepEqual(plan('demo=judge&play=direct'), off);
  assert.deepEqual(plan('demo=judge&play=direct&lang=uk'), off);
  assert.deepEqual(plan('cinematic=trailer'), off);
  assert.deepEqual(plan('view=overview'), off);
  assert.deepEqual(plan('view=camp&play=direct'), off);
  assert.deepEqual(plan('film=1&play=direct'), off);
  assert.deepEqual(plan('play=direct&town=1'), on, 'the direct QA link into the town');
  assert.deepEqual(plan('demo=judge&play=direct&town=1'), on);
  assert.deepEqual(plan('town=altar'), { town: true, spawn: 'altar', flat: false });
  assert.deepEqual(plan('play=direct&town=altar'), { town: true, spawn: 'altar', flat: false });
  assert.deepEqual(plan('play=direct&town=flat'), { town: true, spawn: 'gate', flat: true });
  assert.deepEqual(plan('play=direct&town=altar,flat'), { town: true, spawn: 'altar', flat: true });
  assert.deepEqual(plan('town=1&skip=town'), off, 'skip wins');
  assert.deepEqual(plan('town=0'), off);
});

test('model list: flat models and the town subfolder, names unique, URLs resolved through the folder map', () => {
  const dir = mkdtempSync(path.join(tmpdir(), 'ftf-models-'));
  try {
    mkdirSync(path.join(dir, 'town'));
    mkdirSync(path.join(dir, 'other'));
    writeFileSync(path.join(dir, 'anchor.glb'), 'aaaa');
    writeFileSync(path.join(dir, 'anchor_m.glb'), 'aa');
    writeFileSync(path.join(dir, 'Bad Name.glb'), 'x');
    writeFileSync(path.join(dir, 'notes.txt'), 'x');
    writeFileSync(path.join(dir, 'town', 'town_terrain.glb'), 'tttttt');
    writeFileSync(path.join(dir, 'town', 'town_terrain_m.glb'), 'ttt');
    writeFileSync(path.join(dir, 'town', 'anchor.glb'), 'duplicate');
    writeFileSync(path.join(dir, 'town', 'UPPER.glb'), 'x');
    writeFileSync(path.join(dir, 'other', 'stray.glb'), 'x');
    const { files, dirs } = scanModels(dir);
    assert.deepEqual(files, { anchor: 4, anchor_m: 2, town_terrain: 6, town_terrain_m: 3 }, 'a flat file wins over a duplicate name; unlisted folders are ignored');
    assert.deepEqual(dirs, { town_terrain: 'town/', town_terrain_m: 'town/' });
    assert.deepEqual(scanModels(path.join(dir, 'missing')), { files: {}, dirs: {} });
    const src = modelListSource(dir);
    assert.match(src, /export const MODEL_FILES = \{"anchor":4/);
    assert.match(src, /export const MODEL_DIRS = \{"town_terrain":"town\/"/);
    assert.equal(versionedModelUrl('town_terrain', '/', files.town_terrain, dirs.town_terrain), '/assets/models/town/town_terrain.glb?v=6');
    assert.equal(versionedModelUrl('anchor', '/x/', files.anchor, dirs.anchor), '/x/assets/models/anchor.glb?v=4', 'flat models are unchanged');
  } finally { rmSync(dir, { recursive: true, force: true }); }
  assert.deepEqual([...MODEL_SUBDIRS], ['town']);
  assert.equal(modelUrl('town_altar', '/', 'town/'), '/assets/models/town/town_altar.glb');
  assert.equal(modelUrl('anchor', '/', ''), '/assets/models/anchor.glb');
  assert.equal(modelUrl('anchor', '/', undefined), '/assets/models/anchor.glb');
  for (const bad of ['../', 'town', '/town/', 'a/b/', 'Town/', 'town/../']) { assert.equal(isValidModelDir(bad), false, bad); assert.throws(() => modelUrl('anchor', '/', bad)); }
  assert.ok(isValidModelDir('') && isValidModelDir('town/'));
});

test('chunks: the town scene and its flow stay in the world chunk, never in the play chunk', () => {
  assert.equal(chunkFor('/repo/game/src/scenes/town.js'), 'client-core');
  assert.equal(chunkFor('/repo/game/src/scenes/town-layout.js'), 'client-core');
  assert.equal(chunkFor('/repo/game/src/scenes/town-data.js'), 'client-core');
  assert.equal(chunkFor('/repo/game/src/scenes/town-flow.js'), 'client-core');
});

test('town life: smoke rises and leans downwind, budgets shrink on phones', async () => {
  const { puffOffset, TOWN_LIFE } = await import('../../src/scenes/town-life.js');
  const wind = { x: 0.83, z: -0.56, strength: 0.35 };
  assert.deepEqual(puffOffset(0, wind), [0, 0, 0]);
  const mid = puffOffset(0.5, wind), end = puffOffset(1, wind);
  assert.ok(end[1] > mid[1] && mid[1] > 0, 'rises');
  assert.ok(end[0] * wind.x + end[2] * wind.z > mid[0] * wind.x + mid[2] * wind.z, 'leans further downwind with age');
  assert.equal(puffOffset(1, { ...wind, strength: 0 }, 0.25)[1], end[1], 'calm air changes the lean, not the rise');
  for (const k of ['puffs', 'chimneys', 'birds']) assert.ok(TOWN_LIFE[k][0] < TOWN_LIFE[k][1], k);
});
